314	// reframe parses one archive frame, lets the test alter the payload, and
315	// rebuilds a frame with a consistent declared length and checksum so the
316	// failure under test is content validation, not framing.
317	func reframe(t *testing.T, archive []byte, mutate func(payload []byte) []byte) []byte {
318		t.Helper()
319		magicLen := len(archiveMagic)
320		n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
321		payload := append([]byte(nil), archive[magicLen+4:magicLen+4+n]...)
322		payload = mutate(payload)
323		out := append([]byte(nil), archiveMagic...)
324		var lb [4]byte
325		binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
326		out = append(out, lb[:]...)
327		out = append(out, payload...)
328		sum := sha256.Sum256(payload)
329		out = append(out, sum[:]...)
330		return out
331	}
